-- Ingredients and styles for the bars' signature drinks that only had a
-- description.
--
-- The seeded bar drinks (50 Best, city bars, a decade of 50 Best, the
-- regional lists and the Spirited and James Beard winners) came with a one
-- line description and, for most, no ingredient lines. Without lines a drink
-- can't be found by spirit, gets no flavor profile and can't be checked
-- against a home shelf.
--
-- 1. Ingredient lines, read from each drink's own description: only what it
--    names, in spec order (base spirit first, garnish last), with no
--    measures. A named bottle is the line's ingredient and its generic is the
--    parent ("Roku Gin" under "Gin"), as in a venue's own specs. House
--    preparations keep their names ("Pineapple Campari").
-- 2. The classic it's a version of (riff_of_id), where the name or
--    description says so ("a take on the Gimlet", "Mezcal Negroni"), so it
--    ranks in that classic's list and shows under "Martinis" on Discover.
-- 3. Spirit categories for the generic ingredients that had none (Gin, Rye,
--    Mezcal), which the flavor rules and Discover's spirit filters read.
--
-- Safe to re-run, and only fills gaps: a drink that already has lines keeps
-- them (a researched spec always wins), a riff link is never replaced, and an
-- ingredient's categories are only added when it has none. Drinks from seeds
-- that aren't applied yet are skipped.

-- Seeded drinks don't queue automatic sketches (nobody to bill for them).
SET "app.image_worker" = 'on';

CREATE TEMP TABLE "fill_drinks" ("handle" text, "bar_name" text, "name" text, "classic" text);
CREATE TEMP TABLE "fill_lines" ("handle" text, "bar_name" text, "drink" text, "pos" int, "ingredient" text, "generic" text, "garnish" boolean);
CREATE TEMP TABLE "fill_generics" ("name" text, "category" text);

