-- --- Which drink each row is: the bar's own public drink of that name ---

ALTER TABLE "fill_drinks" ADD COLUMN "item_id" uuid;
UPDATE "fill_drinks" f SET "item_id" = (
    SELECT i.id FROM "public"."items" i
    JOIN "public"."profiles" p ON p.id = i.origin_bar_profile_id
    WHERE p.kind = 'bar'
      AND (p.handle = f.handle OR (f.handle IS NULL AND lower(p.display_name) = lower(f.bar_name)))
      AND i.item_type = 'cocktail' AND i.bar_id IS NULL AND lower(i.name) = lower(f.name)
    ORDER BY i.created_at LIMIT 1
);
DELETE FROM "fill_drinks" WHERE "item_id" IS NULL;

-- --- The classic it's a version of ---

UPDATE "public"."items" i SET
    "riff_of_id" = c.id,
    "origin" = CASE WHEN i.origin = 'Original' THEN 'Varient' ELSE i.origin END
FROM "fill_drinks" f
JOIN "public"."items" c ON c.is_catalog AND lower(c.name) = lower(f.classic)
WHERE i.id = f.item_id AND i.riff_of_id IS NULL AND i.id <> c.id;

-- --- Ingredient lines, only for drinks that have none ---

DELETE FROM "fill_drinks" f WHERE EXISTS (SELECT 1 FROM "public"."recipes" r WHERE r.recipe_item_id = f.item_id);

ALTER TABLE "fill_lines" ADD COLUMN "item_id" uuid;
UPDATE "fill_lines" l SET "item_id" = f.item_id
FROM "fill_drinks" f
WHERE lower(f.name) = lower(l.drink)
  AND f.handle IS NOT DISTINCT FROM l.handle AND f.bar_name IS NOT DISTINCT FROM l.bar_name;
DELETE FROM "fill_lines" WHERE "item_id" IS NULL;

-- Shared ingredients, reusing one with the same name. Generics are
-- searchable; a bar's named bottles and house preps stay out of ingredient
-- search (drink pages still show them), as in the other drink seeds.
INSERT INTO "public"."items" ("name", "item_type", "hide_from_search")
SELECT DISTINCT ON (lower(x.n)) x.n, 'ingredient', NOT x.is_generic
FROM (
    SELECT l.ingredient AS n, EXISTS (SELECT 1 FROM "fill_generics" g WHERE lower(g.name) = lower(l.ingredient)) AS is_generic FROM "fill_lines" l
    UNION ALL
    SELECT l.generic, true FROM "fill_lines" l WHERE l.generic IS NOT NULL
) x
WHERE NOT EXISTS (
    SELECT 1 FROM "public"."items" i WHERE i.item_type = 'ingredient' AND i.bar_id IS NULL AND lower(i.name) = lower(x.n)
)
ORDER BY lower(x.n), x.is_generic DESC;

CREATE TEMP TABLE "fill_ingredients" AS
SELECT DISTINCT ON (lower(name)) lower(name) AS key, id
FROM "public"."items" WHERE item_type = 'ingredient' AND bar_id IS NULL
ORDER BY lower(name), created_at;

INSERT INTO "public"."recipes" ("recipe_item_id", "ingredient_item_id", "parent_ingredient_id", "amount", "unit",
                                "preparation_notes", "is_optional", "sort_order")
SELECT l.item_id, i.id, g.id, NULL, NULL, CASE WHEN l.garnish THEN 'garnish' END, false, l.pos
FROM "fill_lines" l
JOIN "fill_ingredients" i ON i.key = lower(l.ingredient)
LEFT JOIN "fill_ingredients" g ON g.key = lower(l.generic);

-- --- Spirit categories for generics that have none ---

INSERT INTO "public"."item_categories" ("item_id", "category_id", "is_primary")
SELECT i.id, c.id, true
FROM "fill_generics" g
JOIN "fill_ingredients" i ON i.key = lower(g.name)
JOIN LATERAL (
    SELECT c.id FROM "public"."categories" c WHERE c.domain = 'spirit' AND c.name = g.category ORDER BY c.created_at LIMIT 1
) c ON true
WHERE g.category IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM "public"."item_categories" x WHERE x.item_id = i.id);

DROP TABLE "fill_drinks", "fill_lines", "fill_generics", "fill_ingredients";

